      <div class="control">
        <span>Contrast : </span>
        <input type="range" min="-255" max="255" [(ngModel)]="contrast" (input)="updateRaster()" />
        <span> ({{ contrast }})</span>
      </div>
      <div class="control">
        <span>Brightness : </span>
        <input type="range" min="-255" max="255" [(ngModel)]="brightness" (input)="updateRaster()" />
        <span> ({{ brightness }})</span>
